def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we cannot pay much, still try to buy enough to avoid imminent death.
    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read only yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: with supply in [15,25], one unit of water is likely critical.
    # Estimate how many full requirements exist.
    # Use int() to avoid any float index issues; here only for thresholds.
    supply_units = int(supply / float(WATER_REQ))

    # Base bid depends on whether supply is tight.
    # If supply is near MIN_SUPPLY, bid higher to ensure allocation.
    if supply <= float(MIN_SUPPLY) + 0.5:
        base = DAILY_SALARY * 0.75
    elif supply <= float(MIN_SUPPLY) + 5.0:
        base = DAILY_SALARY * 0.6
    else:
        base = DAILY_SALARY * 0.5

    # If we are in danger (low hp or already many no-water days), outbid more.
    danger = (hp <= 2) or (no_water_days >= 2)

    # Cindy likely sets a high-price equilibrium when she has budget; Bob/Eric suggest others may fail.
    # If someone already bid extremely high yesterday, we either match enough or avoid overpaying.
    extreme_prev = highest_prev_bid >= DAILY_SALARY * 0.9

    if danger:
        target = base + (DAILY_SALARY * 0.25)
        if extreme_prev:
            target = max(target, highest_prev_bid * 0.9)
    else:
        # Not in immediate danger: bid enough to beat typical mid bids.
        if extreme_prev:
            # Don't chase the top; bid moderately above base but below extreme.
            target = base + (DAILY_SALARY * 0.1)
        else:
            # If no extreme pressure, slightly above base to secure water.
            target = base + (DAILY_SALARY * 0.12)

    # Final cap: never exceed budget or a reasonable fraction of budget.
    # Prefer not to drain budget unless danger.
    if danger:
        cap = budget
    else:
        cap = min(budget, DAILY_SALARY * 1.2)

    bid = min(cap, target)

    # If supply_units is 0 (very tight), ensure higher bid.
    if supply_units <= 0:
        bid = max(bid, min(budget, DAILY_SALARY * 0.85))

    # Ensure non-negative.
    if bid < 0:
        bid = 0.0

    return float(bid)

