def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    # Determine yesterday's max bid among opponents
    max_prev_bid = None
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev['bid']
            if max_prev_bid is None or bid > max_prev_bid:
                max_prev_bid = bid
    # Base bid: moderate
    bid = DAILY_SALARY * 0.4  # 56
    # Adjust for desperation
    if no_water_days > 0:
        bid = DAILY_SALARY * 0.9  # 126
    elif hp <= 2:
        bid = DAILY_SALARY * 0.85  # 119
    # React to opponent's yesterday bid
    if max_prev_bid is not None:
        high_threshold = DAILY_SALARY * 0.7  # 98
        if max_prev_bid > high_threshold:
            # Opponent was aggressive yesterday; if we are healthy and can afford to wait, bid low
            if hp > 4 and no_water_days == 0:
                bid = min(bid, DAILY_SALARY * 0.3)  # 42
            else:
                # Need to compete: bid slightly above opponent's yesterday bid if we can
                competitor_bid = max_prev_bid + 2.0
                # But don't exceed budget or go crazy
                bid = min(bid, competitor_bid)
        else:
            # Opponents were moderate: just outbid slightly to secure water
            bid = max(bid, max_prev_bid + 1.5)
    # Ensure we can afford
    bid = min(bid, budget)
    # Also ensure positive
    bid = max(bid, 1.0)
    # If supply is very low, consider bidding more aggressively for survival
    if supply <= 16 and no_water_days > 0:
        bid = min(budget, DAILY_SALARY * 0.95)
    return round(bid, 2)
